(7385244, 1159027, 50864, '<td valign="top">Yes terrific. dance of the pea pod.</td>', 'Yes terrific. dance of the pea pod.', '2015-07-10 10:35:19.000000', NULL, 0),
(7385245, 1158775, 50864, '<td valign="top">I love the processing. Very interesting. Well worth being on the last page. If it had been during DPL I bet Team Spleen would have given it proper acknowledgement :-).</td>', 'I love the processing. Very interesting. Well worth being on the last page. If it had been during DPL I bet Team Spleen would have given it proper acknowledgement :-).', '2015-07-10 10:38:53.000000', NULL, 0),
