(7385247, 1157306, 50864, '<td valign="top">You''re just so good.</td>', 'You''re just so good.', '2015-07-10 10:42:01.000000', NULL, 0),
(7385248, 1159025, 50864, '<td valign="top">I didn''t get around to commenting and I am sorry. I had this as my top rated. Perfect flare and lots to hold my interest.</td>', 'I didn''t get around to commenting and I am sorry. I had this as my top rated. Perfect flare and lots to hold my interest.', '2015-07-10 10:44:48.000000', NULL, 0),
(7385252, 1158775, 103142, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Abra:</b></div><hr/><i> I knew this wouldn''t be well received but it didn''t occur to me that this wouldn''t be associated with the musical. I have entered many times shots that are DNMC but this wasn''t meant to be one. I see Emperor Penguins then Elvis and Queen songs fill my head. I wish it got the brown though. </i></td></tr></table> <br/> <br/>You have to have seen it to be able to associate it. I got the reference, but having never seen it, it brought no music to mind. Still simply beautiful, though. I''m glad you entered it, because I''m pleased to have seen it. :)</td>', 'Originally posted by Abra: I knew this wouldn''t be well received but it didn''t occur to me that this wouldn''t be associated with the musical. I have entered many times shots that are DNMC but this wasn''t meant to be one. I see Emperor Penguins then Elvis and Queen songs fill my head. I wish it got the brown though.   You have to have seen it to be able to associate it. I got the reference, but having never seen it, it brought no music to mind. Still simply beautiful, though. I''m glad you entered it, because I''m pleased to have seen it. :)', '2015-07-10 11:09:09.000000', NULL, 0),
